  const examDetails = {
    location: 'Perpetual Help College of Molino',
    date: 'September 16, 2024',
    exam: 'TOEIC LR (Listening & Reading)',
  };

  // Helper function to perform case-insensitive matching for Student ID
  // Allows partial matching to handle input variations
  const matchesSearch = (searchTerm, value) => {
    return value.toLowerCase().includes(searchTerm.toLowerCase());
  };

  // Search function that looks up students by Student ID from the complete database
  // Searches through all 2407 students in STUDENT_DATABASE
  // Returns matching student record or null if not found
  const searchStudent = (input) => {
    if (!input.trim()) {
      setSearchError('');
      return null;
    }

    // Search by Student ID - case-insensitive partial match
    const match = STUDENT_DATABASE.find(student =>
      matchesSearch(input, student.studentId)
    );

    if (!match) {
      setSearchError(`Student ID "${input}" not found in the system.`);
    } else {
      setSearchError(''); // Clear error if student found
    }

    return match;
  };

  // Handle search button click or Enter key press
  const handleSearch = () => {
    const student = searchStudent(searchInput);
    setFoundStudent(student);
  };

  // Handle Enter key press in input field
  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  // Handler to clear all search results and start fresh
  const handleNewSearch = () => {
    setSearchInput('');
    setFoundStudent(null);
    setSearchError('');
  };

